import { hideChartPopover, showChartPopover } from "../chart-board/board-util";

/**
 *
 * @param data - either slice data or point data
 * @param chartContextRoot
 * @returns either return a tooltip div for nivo slice to consume
 * @returns or set the content of a existing hbr-popover with no return
 */
function generateTooltipContent(data, formatFunc?) {
	const infoBlock = `
      <div class="chart-donut__popover">
        <div>
          <div style="background:${data.fill};"></div>
          ${data.id}
        </div>
        <div>
          ${
						formatFunc
							? formatFunc({ formattedValue: data.value })
							: data.formattedValue || data.value
					}
        </div>
      </div>
    `;
	return infoBlock;
}

const toggleDonutLegendPopover = (
	tooltipRef,
	event?,
	id?,
	fill?,
	userConfig?,
) => {
	if (event) {
		const target = userConfig.data.find((r) =>
			userConfig.id
				? Object.prototype.hasOwnProperty.call(r, userConfig.id) &&
				  r[userConfig.id] === id
				: Object.prototype.hasOwnProperty.call(r, "id") && r.id === id,
		);
		if (tooltipRef && target) {
			showChartPopover(
				tooltipRef,
				// not passing data and event, since custom legend and generator is passed with variables
				null,
				event,
				(_data, event, h) =>
					userConfig?.legendTooltip?.(target, fill, event, h),
				() =>
					generateTooltipContent(
						userConfig.id
							? { ...target, id: target[userConfig.id], fill }
							: { ...target, fill },
						userConfig.tooltip,
					),
			);
		}
	} else {
		hideChartPopover(tooltipRef);
	}
};

const toggleDonutSectionPopover = (
	tooltipRef,
	event?,
	datum?,
	itemTooltip?,
	tooltipFormattingFunc?,
) => {
	if (event) {
		const root = event.target.closest("svg");
		// assume third layer is the text container
		const textGroup = root.querySelector(`[datum-id="${datum.id}"]`);

		const color = textGroup.getAttribute("datum-color");
		const value = textGroup.getAttribute("datum-value");
		const formattedValue = textGroup.getAttribute("datum-formatted-value");

		showChartPopover(
			tooltipRef,
			{ id: datum.id, value, formattedValue, color, ...datum },
			event,
			// itemTooltip was passed like itemTooltip(datum, event)
			itemTooltip,
			() =>
				generateTooltipContent(
					{ id: datum.id, value, formattedValue, fill: color },
					tooltipFormattingFunc,
				),
		);
	} else {
		hideChartPopover(tooltipRef);
	}
};

const convertDonutDataToCSV = (arr) => {
	const csv = [];

	// Get the headers from the first object
	const headers = Object.keys(arr[0]);
	csv.push(headers.join(","));

	// Iterate over each object and convert it to a CSV row
	arr.forEach((obj) => {
		const row = headers.map((header) => obj[header]);
		csv.push(row.join(","));
	});

	return csv.join("\n");
};

export {
	toggleDonutLegendPopover,
	toggleDonutSectionPopover,
	convertDonutDataToCSV,
};
