import {
	type DefaultRawDatum,
	type PieSvgProps,
	ResponsivePie as Pie,
} from "@harbor-charts/pie";
import {
	Component,
	Element,
	Host,
	Listen,
	Method,
	Prop,
	h,
} from "@stencil/core";
import * as React from "react";
import { createRoot } from "react-dom/client";
import retargetEvents from "react-shadow-dom-retarget-events";

import { donut } from "@harbor/chart-config/donut";

const {
	getDonutBaseConfig,
	getDonutCategoricalConfig,
	getGaugeConfig,
	resetAllCategoricalArcSelection,
	itemTogglePathUnselect,
} = donut;

import merge from "deepmerge";
import { renderDonutHtmlLegend } from "../../utils/charts/html-legend";
import {
	convertDonutDataToCSV,
	toggleDonutLegendPopover,
	toggleDonutSectionPopover,
} from "./chart-util";

import {
	DONUT_SIZE_PIXELS,
	type DonutSize,
	getCategoricalDonutSizeConfig,
	getDonutCategoricalRenderConfig,
	getDonutChartDimensions,
	getDonutChartSettings,
	isHorizontalDonutLegend,
} from "../../utils/charts/donut";
import { hasSlot } from "../../utils/slot";
import { browserDownloadCsv } from "../chart-board/board-util";
import { omitChartConfigKeys } from "../chart-board/chart-config-util";
import {
	type ChartPopoverOptions,
	applyChartPopoverOptions,
	isChartPopoverSelfManaged,
	resolveChartPopoverOptions,
} from "../chart-board/popover-options";
type HbrTooltipFunctions = {
	itemTooltip?: (data, event, h) => string | object | false;
	legendTooltip?: (data, event, h) => string | object | false;
};

type DonutChartConfig = Omit<Partial<PieSvgProps<DefaultRawDatum>>, "tooltip"> &
	HbrTooltipFunctions & {
		arcLinkLabelsHtml?: {
			width?: number | ((datum: unknown) => number);
		};
		legendLayout?: "svg" | "html";
		missingDataLabel?: string;
		isChartFocusable?: boolean;
		centerSlotName?: string;
		status?: boolean;
	};

const PIE_DEFAULT_CONFIG: Pick<
	DonutChartConfig,
	"innerRadius" | "borderWidth" | "borderColor"
> = {
	innerRadius: 0,
	borderWidth: 2,
	borderColor: "var(--base-bg-weak-default)",
};

type ConfigWithNivoTooltip = DonutChartConfig & { tooltip?: unknown };

type DonutLegendPopoverConfig = {
	popoverOptions?: ChartPopoverOptions;
};
type DonutDatum = { id: string | number };
type DonutLegend = DonutDatum & { color: string };
type DonutReactEvent = React.MouseEvent<Element> | React.FocusEvent<Element>;

/**
 * @since 1.1.3
 * @status stable
 * @part chart - The chart element
 * @part header - The header element
 * @part popover-body - The popover body element, check hbr-popover for more details
 * @part popover-popup - The popover popup element,  check hbr-popover for more details
 * @part popover-arrow - The popover arrow element,  check hbr-popover for more details
 *
 * @slot header - Slot for header
 * @slot header-title - Slot for header title
 * @slot header-action - Slot for header action
 * @slot footer - Slot for footer
 * @slot loading-state - Slot for loading state
 * @slot empty-state - Slot for empty state
 * @slot content - Slot for popover content
 * @slot center-value - Gauge center value
 * @slot center-suffix - Gauge center value suffix
 * @slot center-label - Optional gauge center label below the value row
 * @slot center-sublabel - Optional categorical donut center supporting text
 */
@Component({
	tag: "hbr-donut-chart",
	styleUrl: "style.scss",
	shadow: true,
})
export class HbrDonutChart {
	chartRef: HTMLElement;
	tooltipRef: HTMLHbrPopoverElement;
	boardRef: HTMLHbrChartBoardElement;
	observer: MutationObserver = null;
	htmlLegendResizeObserver: ResizeObserver = null;
	htmlLegendRef: HTMLElement = null;

	/** Chart configuration object. Refer to https://nivo.rocks/pie */
	@Prop({ mutable: true }) config: DonutChartConfig = {
		data: [],
	};
	/** Chart width */
	@Prop() width = "100%";
	/** Chart height */
	@Prop() height = "360px";
	/** Fixed chart size. The chart steps down to smaller supported sizes when needed. */
	@Prop({ reflect: true }) size?: DonutSize;
	/** Chart loading flag */
	@Prop() loading = false;

	/** New Magnetic UX chart type */
	@Prop({ reflect: true }) categorical = false;

	/** Enable gauge behavior with optional hover/tooltip interaction. */
	@Prop({ reflect: true }) gauge = false;
	/** Final config before rendering, param1 is the final config, your customization should be done here */
	@Prop() modifyHbrConfig: (
		config: DonutChartConfig,
		createElement: typeof React.createElement,
		util: typeof donut,
	) => ConfigWithNivoTooltip;

	/** Default popover props. Set `selfManaged` to let a categorical popover manage its own open and close behavior. */
	@Prop() popoverOptions: ChartPopoverOptions;

	@Element() private el: HTMLHbrDonutChartElement;

	@Prop() variant: "donut" | "pie" | "gauge";

	/** Public method for download data, use customFunc to create your own way to download data, such as pdf */
	@Method()
	async download(filename = "Export.csv", customFunc?: (data) => void) {
		if (customFunc) {
			customFunc(this.config.data);
		} else {
			browserDownloadCsv(convertDonutDataToCSV(this.config.data), filename);
		}
	}

	/** Public method to get popover reference, client can use this to control magnetic UX popover externally */
	@Method()
	async getPopoverRef() {
		return this.tooltipRef;
	}

	// saved react object after it is rendered
	// this is for update since react will complain if creating root again during update
	private contextRoot = null;
	private activePopoverSelfManaged: boolean | null = null;
	private warnedAboutNivoTooltip = false;
	private chartFocusInHandler = (event: FocusEvent) => {
		const target = event.target;
		if (target instanceof SVGElement || target instanceof HTMLElement) {
			target.style.setProperty("outline", "none", "important");
		}
		this.chartRef?.classList.add("gauge-chart--focused");
	};
	private chartFocusOutHandler = () => {
		this.chartRef?.classList.remove("gauge-chart--focused");
	};

	private isGaugeMode() {
		return this.gauge || this.variant === "gauge";
	}

	private getChartConfig() {
		const config = omitChartConfigKeys(this.config as ConfigWithNivoTooltip, [
			"tooltip",
		]) as DonutChartConfig;
		return this.categorical && this.variant === "pie"
			? { ...PIE_DEFAULT_CONFIG, ...config }
			: config;
	}

	private getLegendPopoverOptions() {
		return (
			this.config.legends?.[0] as unknown as
				| DonutLegendPopoverConfig
				| undefined
		)?.popoverOptions;
	}

	private getPopoverOptions(override?: ChartPopoverOptions) {
		return resolveChartPopoverOptions(
			{
				distance: this.categorical ? 0 : 10,
				variant: "chart",
				placement: "top",
			},
			this.popoverOptions,
			this.categorical,
			override,
		);
	}

	private applyActivePopoverOptions(override?: ChartPopoverOptions) {
		this.activePopoverSelfManaged = this.isPopoverSelfManaged(override);
		applyChartPopoverOptions(this.tooltipRef, this.getPopoverOptions(override));
	}

	private isPopoverSelfManaged(override?: ChartPopoverOptions) {
		return isChartPopoverSelfManaged(
			this.categorical,
			this.popoverOptions,
			override,
		);
	}

	private getChartSettings() {
		return getDonutChartSettings(
			this.getChartConfig(),
			this.width,
			this.el,
			this.isGaugeMode(),
			this.categorical ? this.size : undefined,
			this.categorical,
		);
	}

	private isStatusMode() {
		return this.isGaugeMode() && this.getChartConfig().status === true;
	}

	private clearHtmlLegend = () => {
		this.htmlLegendRef?.remove();
		this.htmlLegendRef = null;
		this.htmlLegendResizeObserver?.disconnect();
		this.htmlLegendResizeObserver = null;
	};

	// Keep the bottom legend in the chart-board legend slot as real HTML so it can
	// use native button behavior and normal HTML layout instead of SVG coordinates.
	private syncHtmlLegend = () => {
		const config = this.getChartConfig();
		if (!this.categorical || config.legendLayout !== "html") {
			this.clearHtmlLegend();
			return;
		}
		if (!this.boardRef?.isConnected) return;

		renderDonutHtmlLegend(this.boardRef, config);
		this.htmlLegendRef = this.boardRef.querySelector(
			".chart-donut__categorical-legend",
		);
		this.syncHtmlLegendHeight();
		this.observeHtmlLegendResize();
	};

	private syncHtmlLegendHeight = () => {
		const container = this.boardRef?.shadowRoot?.querySelector<HTMLElement>(
			".chart-board__container",
		);
		const legend = container?.querySelector<HTMLSlotElement>(
			'slot[name="legend"]',
		);
		const footer = container?.querySelector<HTMLElement>(
			".chart-board__footer",
		);
		if (!container || !legend || !footer) return;

		const headerHeight = container
			.querySelector<HTMLSlotElement>('slot[name="header"]')
			?.assignedElements()
			.reduce(
				(height, element) => height + element.getBoundingClientRect().height,
				0,
			);
		const chartHeight = this.chartRef?.getBoundingClientRect().height ?? 0;
		const legendHeight = legend
			.assignedElements()
			.reduce(
				(height, element) => height + element.getBoundingClientRect().height,
				0,
			);
		const footerHeight = Math.max(
			footer.getBoundingClientRect().height,
			footer.scrollHeight,
		);
		const requiredHeight =
			(headerHeight ?? 0) + chartHeight + legendHeight + footerHeight;
		if (requiredHeight > 0) {
			const nextHeight = `${Math.ceil(requiredHeight)}px`;
			if (this.el.style.height !== nextHeight) {
				this.el.style.height = nextHeight;
			}
			if (this.boardRef.style.height !== nextHeight) {
				this.boardRef.style.height = nextHeight;
			}
		}
	};

	private observeHtmlLegendResize = () => {
		this.htmlLegendResizeObserver?.disconnect();
		const legend = this.boardRef?.querySelector<HTMLElement>(
			".chart-donut__categorical-legend",
		);
		if (!legend || typeof ResizeObserver === "undefined") return;

		this.htmlLegendResizeObserver = new ResizeObserver(() =>
			this.syncHtmlLegendHeight(),
		);
		this.htmlLegendResizeObserver.observe(legend);
	};

	private getChartInteractivity() {
		const config = this.getChartConfig();
		return this.isGaugeMode()
			? config.isInteractive ?? false
			: config.isInteractive ?? true;
	}

	private getChartFocusability() {
		const config = this.getChartConfig();
		return this.isGaugeMode()
			? config.isFocusable ?? false
			: config.isFocusable ?? true;
	}

	private syncChartSvgFocusability() {
		const config = this.getChartConfig();
		const svg = this.chartRef?.querySelector("svg") as SVGSVGElement | null;
		if (!svg) {
			return;
		}
		this.chartRef
			.querySelectorAll(".legend-event-rect ~ text")
			.forEach((text) =>
				text.classList.toggle("donut-legend-text", this.categorical),
			);

		svg.style.setProperty("outline", "none", "important");

		if (config.isChartFocusable !== false) {
			svg.setAttribute("tabindex", "0");
			svg.setAttribute("focusable", "true");
		} else {
			svg.removeAttribute("tabindex");
			svg.removeAttribute("focusable");
		}
	}

	componentDidLoad() {
		void this.renderChart().then(() => this.syncHtmlLegend());
		retargetEvents(this.el.shadowRoot);
		this.chartRef.addEventListener("focusin", this.chartFocusInHandler);
		this.chartRef.addEventListener("focusout", this.chartFocusOutHandler);
		this.observer = new MutationObserver(() => {
			this.syncChartSvgFocusability();
		});
		this.observer.observe(this.chartRef, { subtree: true, childList: true });
	}

	componentShouldUpdate() {
		if (this.getChartInteractivity()) {
			itemTogglePathUnselect(null, this.chartRef);
		}
		return this.renderChart().then(() => this.syncHtmlLegend());
	}

	@Listen("click", { target: "document", passive: true })
	handleOutsideClick(event: MouseEvent) {
		if (!this.getChartInteractivity()) {
			return;
		}
		// The chart reference can be cleared while React switches between keyed variants.
		if (!this.chartRef) {
			return;
		}

		if (this.categorical) {
			resetAllCategoricalArcSelection(this.chartRef);
			if (!(this.activePopoverSelfManaged ?? this.isPopoverSelfManaged())) {
				toggleDonutSectionPopover(this.tooltipRef);
				toggleDonutLegendPopover(this.tooltipRef);
			}
		} else {
			itemTogglePathUnselect(event, this.chartRef);
		}
	}

	@Listen("mouseout", { passive: true })
	handleHoverOut() {
		if (
			this.tooltipRef &&
			!(this.activePopoverSelfManaged ?? this.isPopoverSelfManaged())
		) {
			this.tooltipRef.open = false;
		}
	}

	disconnectedCallback() {
		this.chartRef?.removeEventListener("focusin", this.chartFocusInHandler);
		this.chartRef?.removeEventListener("focusout", this.chartFocusOutHandler);
		this.chartRef?.classList.remove("gauge-chart--focused");
		if (this.observer) {
			this.observer.disconnect();
			this.observer = null;
		}
		this.htmlLegendResizeObserver?.disconnect();
		this.htmlLegendResizeObserver = null;
	}

	renderChart = async () => {
		const config = this.getChartConfig();
		const configWithNivoTooltip = this.config as ConfigWithNivoTooltip;
		if (
			!this.warnedAboutNivoTooltip &&
			configWithNivoTooltip.tooltip !== undefined
		) {
			console.warn(
				"hbr-donut-chart: config.tooltip is not supported. Use itemTooltip or legendTooltip instead.",
			);
			this.warnedAboutNivoTooltip = true;
		}
		const isGaugeMode = this.isGaugeMode();
		const isInteractive = this.getChartInteractivity();
		const isFocusable = this.getChartFocusability();
		const {
			fixedSize,
			interactionMargin,
			legendRows,
			legendRowHeight,
			config: categoricalConfig,
		} = this.getChartSettings();
		const categoricalSizeConfig =
			this.categorical && fixedSize
				? getCategoricalDonutSizeConfig(categoricalConfig, fixedSize)
				: categoricalConfig;
		const categoricalRenderConfig = this.categorical
			? getDonutCategoricalRenderConfig(
					categoricalSizeConfig,
					fixedSize,
					true,
					legendRows,
					legendRowHeight,
					interactionMargin,
			  )
			: categoricalConfig;
		const hasCategoricalCenterSlots =
			hasSlot(this.el, "center-label") || hasSlot(this.el, "center-sublabel");
		const runtimeConfig = isGaugeMode
			? getGaugeConfig(
					config,
					isInteractive,
					isFocusable,
					hasSlot(this.el, "center-value"),
					this.categorical,
			  )
			: this.categorical && hasCategoricalCenterSlots
			  ? {
						...categoricalRenderConfig,
						centerSlotName: "center",
						centerContentLayout: "donut" as const,
				  }
			  : categoricalRenderConfig;
		const tooltipConfig = config as ConfigWithNivoTooltip &
			PieSvgProps<DefaultRawDatum> &
			HbrTooltipFunctions;
		const legendPopoverOptions = this.getLegendPopoverOptions();
		const showSectionPopover = (node: DonutDatum, event: DonutReactEvent) => {
			this.applyActivePopoverOptions();
			toggleDonutSectionPopover(
				this.tooltipRef,
				event,
				node,
				tooltipConfig.itemTooltip,
				tooltipConfig.tooltip,
			);
		};
		const hidePopover = () => {
			if (!this.isPopoverSelfManaged()) {
				toggleDonutSectionPopover(this.tooltipRef);
			}
		};
		const showLegendPopover = (data: DonutLegend, event: DonutReactEvent) => {
			this.applyActivePopoverOptions(legendPopoverOptions);
			toggleDonutLegendPopover(
				this.tooltipRef,
				event,
				data.id,
				data.color,
				config,
			);
		};
		const hideLegendPopover = () => {
			if (!this.isPopoverSelfManaged(legendPopoverOptions)) {
				toggleDonutLegendPopover(this.tooltipRef);
			}
		};
		const hideLegendPopoverOnBlur = () => {
			this.activePopoverSelfManaged = null;
			toggleDonutLegendPopover(this.tooltipRef);
		};

		const baseConfig = this.categorical
			? getDonutCategoricalConfig(
					runtimeConfig as unknown as Parameters<
						typeof getDonutCategoricalConfig
					>[0],
					{
						itemsEventHandlers:
							isGaugeMode && !isInteractive
								? {}
								: {
										onMouseEnter: showSectionPopover,
										onMouseLeave: hidePopover,
										onFocus: showSectionPopover,
										onBlur: () => toggleDonutSectionPopover(this.tooltipRef),
								  },
						legendsEventHandlers:
							isGaugeMode && !isInteractive
								? {}
								: {
										onMouseEnter: showLegendPopover,
										onMouseLeave: hideLegendPopover,
										onFocus: showLegendPopover,
										onBlur: hideLegendPopoverOnBlur,
										onClick: showLegendPopover,
								  },
					},
					{
						isGauge: isGaugeMode,
						isGaugeBackground: isGaugeMode && !this.isStatusMode(),
						createTag: (value) =>
							React.createElement(
								"hbr-tag",
								{
									size: "small",
									className: "--categorical-donut-link-label-value",
								},
								value,
							),
					},
			  )
			: getDonutBaseConfig(
					runtimeConfig as unknown as Parameters<typeof getDonutBaseConfig>[0],
					{
						itemsEventHandlers:
							isGaugeMode && !isInteractive
								? {}
								: {
										onMouseEnter: showSectionPopover,
										onMouseLeave: hidePopover,
										onFocus: showSectionPopover,
										onBlur: () => toggleDonutSectionPopover(this.tooltipRef),
								  },
						legendsEventHandlers:
							isGaugeMode && !isInteractive
								? {}
								: {
										onMouseEnter: showLegendPopover,
										onMouseLeave: hideLegendPopover,
										onFocus: showLegendPopover,
										onBlur: hideLegendPopoverOnBlur,
										onClick: showLegendPopover,
								  },
					},
			  );

		const existingEventHandlers = isGaugeMode
			? {}
			: {
					onMouseEnter: baseConfig.onMouseEnter,
					onMouseLeave: baseConfig.onMouseLeave,
					onClick: baseConfig.onClick,
					onblur: baseConfig.onBlur,
					onFocus: baseConfig.onFocus,
			  };

		let fullConfig = merge(
			baseConfig as unknown as DonutChartConfig,
			runtimeConfig as unknown as DonutChartConfig,
			{
				customMerge: (key) => {
					if (key === "legends") {
						return (a, b) => {
							if (this.categorical) {
								return a.length > b.length
									? a
									: b.map((r, i) => ({ ...a[i], ...r }));
							}
							return a.length > b.length
								? a.map((r, i) => ({ ...r, ...b[i] }))
								: b.map((r, i) => ({ ...a[i], ...r }));
						};
					}
				},
			},
		) as DonutChartConfig;

		fullConfig = {
			...fullConfig,
			...existingEventHandlers,
		} as DonutChartConfig;

		if (this.modifyHbrConfig) {
			fullConfig = this.modifyHbrConfig(fullConfig, React.createElement, donut);
		}

		if (isGaugeMode) {
			fullConfig = {
				...fullConfig,
				isInteractive,
				isFocusable,
				onMouseEnter: isInteractive ? fullConfig.onMouseEnter : undefined,
				onMouseLeave: isInteractive ? fullConfig.onMouseLeave : undefined,
				onMouseMove: isInteractive ? fullConfig.onMouseMove : undefined,
				onClick: isInteractive ? fullConfig.onClick : undefined,
				onMouseDown: isInteractive ? fullConfig.onMouseDown : undefined,
				onFocus: isInteractive && isFocusable ? fullConfig.onFocus : undefined,
				onBlur: isInteractive && isFocusable ? fullConfig.onBlur : undefined,
			};
		}
		const pieElement = React.createElement(
			Pie,
			fullConfig as PieSvgProps<DefaultRawDatum>,
			null,
		);
		if (!this.chartRef.innerHTML.length) {
			const newRoot = createRoot(this.chartRef);
			await newRoot.render(pieElement);
			this.contextRoot = newRoot;
		} else {
			await this.contextRoot.render(pieElement);
		}

		if (this.boardRef.setChartConfig) {
			this.boardRef.setChartConfig(fullConfig);
		}

		this.syncChartSvgFocusability();
	};

	render() {
		const config = this.getChartConfig();
		const chartSettings = this.getChartSettings();
		const { chartWidth, chartHeight = this.height } = getDonutChartDimensions(
			config,
			this.width,
			chartSettings,
		);
		const hasLegend = Boolean(config.legends?.length);
		const hasArcLinkLabels = config.enableArcLinkLabels !== false;
		const horizontalMargin =
			(config.margin?.left ?? 0) + (config.margin?.right ?? 0);
		const shouldUseFixedDonutStyle =
			Boolean(chartSettings.fixedSize) && (hasLegend || !hasArcLinkLabels);
		const shouldFixDonutAreaHeight =
			shouldUseFixedDonutStyle &&
			(!hasLegend ||
				config.legendLayout === "html" ||
				isHorizontalDonutLegend(config));
		const fixedDonutStyle = shouldUseFixedDonutStyle
			? {
					width: `${
						chartSettings.fixedChartWidth ??
						DONUT_SIZE_PIXELS[chartSettings.fixedSize] + horizontalMargin
					}px`,
					minWidth: `${
						chartSettings.fixedChartWidth ??
						DONUT_SIZE_PIXELS[chartSettings.fixedSize] + horizontalMargin
					}px`,
					minHeight: `${
						DONUT_SIZE_PIXELS[chartSettings.fixedSize] +
						chartSettings.interactionMargin * 2
					}px`,
					...(shouldFixDonutAreaHeight && {
						height: `${
							DONUT_SIZE_PIXELS[chartSettings.fixedSize] +
							(config.margin?.top ?? 0) +
							(config.margin?.bottom ?? 0) +
							chartSettings.interactionMargin * 2
						}px`,
						flex: "0 0 auto",
					}),
					alignSelf: "center",
			  }
			: undefined;

		this.el.style.width = this.width;
		this.el.style.height = chartHeight;
		let type: "gauge" | "none" | "pie" | "donut" = "donut";
		if (this.isGaugeMode()) {
			type = "gauge";
		} else if (this.variant === "pie" || config.innerRadius === 0) {
			type = "pie";
		}

		const popoverOptions = resolveChartPopoverOptions(
			{
				distance: this.categorical ? 0 : 10,
				variant: "chart",
			},
			this.popoverOptions,
			this.categorical,
		);

		// Chart-managed visibility remains the default due to the chart mesh.
		return (
			<Host
				data-gauge={this.categorical && this.isGaugeMode() ? "true" : null}
				data-status={this.isStatusMode() ? "true" : null}
			>
				{!config.data?.length && (this.categorical || this.isGaugeMode()) && (
					<div slot="header" part="header" class="chart-donut__header">
						<slot name="header">
							<div>
								<slot name="header-title" />
							</div>
							<div>
								<slot name="header-action" />
							</div>
						</slot>
					</div>
				)}
				<hbr-chart-board
					type={this.categorical ? "categorical" : type}
					ref={(el) => {
						this.boardRef = el;
					}}
					isLoading={this.loading}
					isEmpty={!config.data?.length}
					style={{
						width: chartWidth,
						height: chartHeight,
					}}
					exportparts="empty-state-illustration, empty-state-image, loading-state-illustration, loading-state-image"
				>
					<hbr-popover
						{...popoverOptions}
						ref={(el) => {
							this.tooltipRef = el;
						}}
						part="popover"
						exportparts="base__popup:popover-popup, base__arrow:popover-arrow, body:popover-body"
						anchor=""
					>
						<div slot="content" />
					</hbr-popover>
					{(config.data?.length ||
						(!this.categorical && !this.isGaugeMode())) && (
						<div slot="header" part="header" class="chart-donut__header">
							<slot name="header">
								<div>
									<slot name="header-title" />
								</div>
								<div>
									<slot name="header-action" />
								</div>
							</slot>
						</div>
					)}
					<div
						ref={(el) => {
							this.chartRef = el;
						}}
						class={`--hbr-donut --donut-chart ${
							this.categorical ? "--categorical" : ""
						}`}
						style={fixedDonutStyle}
						part="chart"
					/>
					<slot name="footer" />
					<slot slot="loading-state" name="loading-state" />
					<slot slot="empty-state" name="empty-state" />
				</hbr-chart-board>
			</Host>
		);
	}
}
