export type DonutSize = "small" | "medium" | "large";

export const DONUT_SIZE_PIXELS: Record<DonutSize, number> = {
	large: 375,
	medium: 240,
	small: 168,
};

export const DONUT_HORIZONTAL_LEGEND_GAP = 16;

export const getAvailableDonutWidth = (
	width: string,
	element: HTMLElement | null,
) => {
	const requestedWidth = Number.parseFloat(width);
	if (/^\d+(?:\.\d+)?px$/.test(width) && Number.isFinite(requestedWidth)) {
		return requestedWidth;
	}
	const parentWidth =
		element?.parentElement?.getBoundingClientRect().width ?? 0;
	if (parentWidth) {
		return parentWidth;
	}
	return element?.getBoundingClientRect().width || undefined;
};

export type DonutArcLinkLabelGutter = {
	left: number;
	right: number;
};

export const getDonutArcLinkLabelGutter = (
	data: ReadonlyArray<{ id: unknown; value: unknown }> = [],
	labelWidth?: number,
	size?: DonutSize,
	activeOuterRadiusOffset = 10,
): DonutArcLinkLabelGutter => {
	// Estimate each label at 7px per label/value character plus 32px for the
	// value tag and its gap.
	const calculatedLabelWidth = Math.min(
		160,
		Math.max(
			72,
			...data.map(
				({ id, value }) =>
					String(id).length * 7 + String(value).length * 7 + 32,
			),
		),
	);
	const fallbackGutter = 54 + (labelWidth ?? calculatedLabelWidth);

	if (!size || !data.length) {
		return { left: fallbackGutter, right: fallbackGutter };
	}

	const radius = DONUT_SIZE_PIXELS[size] / 2;
	const total = data.reduce((sum, datum) => {
		const value = Number(datum.value);
		return Number.isFinite(value) && value > 0 ? sum + value : sum;
	}, 0);
	if (!total) {
		return { left: fallbackGutter, right: fallbackGutter };
	}

	const arcLinkLabelsOffset = size === "small" ? 0 : 2;
	const arcLinkLabelsStraightLength = size === "small" ? 24 : 36;
	const arcLinkLabelsTextOffset = 6;
	const radialDistance = radius + arcLinkLabelsOffset + activeOuterRadiusOffset;
	let startAngle = 0;
	let left = 0;
	let right = 0;

	data.forEach((datum) => {
		const value = Number(datum.value);
		if (!Number.isFinite(value) || value <= 0) {
			return;
		}

		const angle = startAngle + (value / total) * Math.PI;
		const sin = Math.sin(angle - Math.PI / 2);
		const cos = Math.cos(angle - Math.PI / 2);
		const width =
			labelWidth ??
			Math.min(
				160,
				Math.max(
					72,
					String(datum.id).length * 7 + String(datum.value).length * 7 + 32,
				),
			);
		const requiredGutter = Math.ceil(
			width +
				arcLinkLabelsStraightLength +
				(sin > 0 ? sin * 12 : 0) +
				arcLinkLabelsTextOffset +
				radialDistance * (cos >= 0 ? cos : -cos) -
				radius,
		);

		if (cos >= 0) {
			right = Math.max(right, requiredGutter);
		} else {
			left = Math.max(left, requiredGutter);
		}
		startAngle += (value / total) * 2 * Math.PI;
	});

	return { left: Math.max(0, left), right: Math.max(0, right) };
};

type DonutConfig = {
	data?: ReadonlyArray<unknown>;
	enableArcLinkLabels?: unknown;
	arcLinkLabelsHtml?: {
		width?: number | ((datum: unknown) => number);
	};
	activeOuterRadiusOffset?: number;
	legends?: ReadonlyArray<unknown>;
	legendLayout?: "svg" | "html";
	margin?: {
		top?: number;
		right?: number;
		bottom?: number;
		left?: number;
	};
};

const getDonutLegendHorizontalPadding = (legend: Record<string, unknown>) => {
	const padding = legend.padding;
	if (typeof padding === "number") {
		return padding * 2;
	}
	if (padding && typeof padding === "object" && !Array.isArray(padding)) {
		return (
			Number((padding as Record<string, unknown>).left ?? 0) +
			Number((padding as Record<string, unknown>).right ?? 0)
		);
	}
	return 0;
};

export const isHorizontalDonutLegend = (config: DonutConfig) => {
	const legend = config.legends?.[0];
	return Boolean(
		legend &&
			typeof legend === "object" &&
			!Array.isArray(legend) &&
			(legend as Record<string, unknown>).horizontal === true,
	);
};

export const getDonutHorizontalLegendWidth = (config: DonutConfig) => {
	const legend = config.legends?.[0];
	if (!legend || typeof legend !== "object" || Array.isArray(legend)) {
		return 0;
	}
	const legendConfig = legend as Record<string, unknown>;
	const itemWidth = Number(legendConfig.itemWidth ?? 100);
	return (
		(Number.isFinite(itemWidth) ? itemWidth : 100) +
		getDonutLegendHorizontalPadding(legendConfig)
	);
};

export const getDonutHorizontalLegendMargin = (config: DonutConfig) =>
	getDonutHorizontalLegendWidth(config) + DONUT_HORIZONTAL_LEGEND_GAP;

export type DonutLegendLayout = {
	rows: number;
	rowHeight: number;
};

const HTML_LEGEND_ITEM_GAP = 4;
const HTML_LEGEND_COLUMN_GAP = 24;
const HTML_LEGEND_ITEM_HEIGHT = 20;
const HTML_LEGEND_SYMBOL_SIZE = 16;

const getDonutLegendLabels = (config: DonutConfig): string[] => {
	const legend = config.legends?.[0];
	if (
		legend &&
		typeof legend === "object" &&
		!Array.isArray(legend) &&
		Array.isArray((legend as Record<string, unknown>).data)
	) {
		return ((legend as Record<string, unknown>).data as unknown[]).map(
			(datum) =>
				String(
					datum && typeof datum === "object"
						? (datum as Record<string, unknown>).label ??
								(datum as Record<string, unknown>).id
						: datum,
				),
		);
	}

	return (config.data ?? []).map((datum, index) => {
		const record = datum as Record<string, unknown>;
		return String(record.label ?? record.id ?? index);
	});
};

export const getDonutLegendLayout = (
	config: DonutConfig,
	availableWidth: number | undefined,
	categorical = false,
): DonutLegendLayout => {
	if (!categorical) {
		return { rows: 1, rowHeight: 0 };
	}

	const legend = config.legends?.[0];
	if (
		!legend ||
		!availableWidth ||
		typeof legend !== "object" ||
		Array.isArray(legend)
	) {
		return { rows: 1, rowHeight: 0 };
	}

	const legendConfig = legend as Record<string, unknown>;
	const isHorizontalLegend = legendConfig.horizontal === true;
	const anchor =
		legendConfig.anchor ?? (isHorizontalLegend ? "right" : "bottom");
	const direction =
		legendConfig.direction ?? (isHorizontalLegend ? "column" : "row");
	if (
		anchor !== "bottom" ||
		(config.legendLayout !== "html" && direction !== "row")
	) {
		return { rows: 1, rowHeight: 0 };
	}

	if (config.legendLayout === "html") {
		const itemWidths = getDonutLegendLabels(config).map(
			(label) =>
				Math.max(HTML_LEGEND_SYMBOL_SIZE, label.length * 7) +
				HTML_LEGEND_ITEM_GAP +
				HTML_LEGEND_SYMBOL_SIZE,
		);
		let rows = 1;
		let rowWidth = 0;
		for (const itemWidth of itemWidths) {
			const nextWidth = rowWidth
				? rowWidth + HTML_LEGEND_COLUMN_GAP + itemWidth
				: itemWidth;
			if (rowWidth && nextWidth > availableWidth) {
				rows += 1;
				rowWidth = itemWidth;
			} else {
				rowWidth = nextWidth;
			}
		}
		return {
			rows,
			rowHeight: HTML_LEGEND_ITEM_HEIGHT + HTML_LEGEND_ITEM_GAP,
		};
	}
	return { rows: 1, rowHeight: 0 };
};

export type DonutChartSettings<T extends DonutConfig = DonutConfig> = {
	fixedSize?: DonutSize;
	fixedChartWidth?: number;
	horizontalGutter: DonutArcLinkLabelGutter;
	interactionMargin: number;
	legendRows: number;
	legendRowHeight: number;
	config: T;
};

const DEFAULT_DONUT_MARGIN = {
	top: 40,
	right: 60,
	bottom: 90,
	left: 60,
};

const DEFAULT_DONUT_LEGEND_MARGIN = {
	...DEFAULT_DONUT_MARGIN,
	right: 0,
	left: 0,
};

const HTML_LEGEND_PADDING = 16;
const HTML_LEGEND_ROW_GAP = 4;
const DONUT_LEGEND_EXTRA_INTERACTION_MARGIN = 16;

export const getDonutChartSettings = <T extends DonutConfig>(
	config: T,
	width: string,
	element: HTMLElement | null,
	gauge: boolean,
	size?: DonutSize,
	categorical = false,
): DonutChartSettings<T> => {
	const availableWidth = getAvailableDonutWidth(width, element);
	const fixedSize = categorical && size && !gauge ? size : undefined;
	const hasArcLinkLabels = config.enableArcLinkLabels !== false;
	const labelWidth = config.arcLinkLabelsHtml?.width;
	const horizontalGutter = getDonutArcLinkLabelGutter(
		config.data as ReadonlyArray<{ id: unknown; value: unknown }>,
		typeof labelWidth === "number" ? labelWidth : undefined,
		fixedSize,
		config.activeOuterRadiusOffset ?? 10,
	);
	const legendLayout = getDonutLegendLayout(
		config,
		availableWidth,
		categorical,
	);
	const hasExtraLegendInteractionMargin =
		fixedSize &&
		(isHorizontalDonutLegend(config) || config.legendLayout === "html");
	const interactionMargin = gauge
		? 0
		: fixedSize
		  ? (config.activeOuterRadiusOffset ?? 10) +
			  (hasExtraLegendInteractionMargin
					? DONUT_LEGEND_EXTRA_INTERACTION_MARGIN
					: 0)
		  : 0;
	const horizontalMargin =
		(config.margin?.left ?? 0) + (config.margin?.right ?? 0);
	const fixedChartWidth =
		fixedSize && (isHorizontalDonutLegend(config) || !hasArcLinkLabels)
			? DONUT_SIZE_PIXELS[fixedSize] +
			  horizontalMargin +
			  interactionMargin * 2 +
			  (isHorizontalDonutLegend(config)
					? getDonutHorizontalLegendMargin(config)
					: 0)
			: undefined;
	const renderedConfig =
		fixedSize && hasArcLinkLabels && !config.legends?.length && !config.margin
			? {
					...config,
					margin: {
						top: 14,
						right: horizontalGutter.right,
						bottom: 14,
						left: horizontalGutter.left,
					},
			  }
			: config;

	return {
		fixedSize,
		fixedChartWidth,
		horizontalGutter,
		interactionMargin,
		legendRows: legendLayout.rows,
		legendRowHeight: legendLayout.rowHeight,
		config: renderedConfig as T,
	};
};

export const getDonutCategoricalRenderConfig = <T extends DonutConfig>(
	config: T,
	fixedSize: DonutSize | undefined,
	categorical: boolean,
	legendRows: number,
	legendRowHeight: number,
	interactionMargin: number,
) => {
	const legend = config.legends?.[0];
	const hasLegend = Boolean(config.legends?.length);
	const isHorizontalLegend = isHorizontalDonutLegend(config);
	const horizontalLegendMargin = isHorizontalLegend
		? getDonutHorizontalLegendMargin(config)
		: 0;
	const legendAnchor =
		legend && typeof legend === "object" && !Array.isArray(legend)
			? (legend as Record<string, unknown>).anchor ??
			  (isHorizontalLegend ? "right" : "bottom")
			: "bottom";
	const legendDirection =
		legend && typeof legend === "object" && !Array.isArray(legend)
			? (legend as Record<string, unknown>).direction ??
			  (isHorizontalLegend ? "column" : "row")
			: "row";
	const hasBottomRowLegend =
		legend &&
		typeof legend === "object" &&
		!Array.isArray(legend) &&
		legendAnchor === "bottom" &&
		legendDirection === "row";
	const hasHtmlLegend =
		config.legendLayout === "html" && Boolean(hasBottomRowLegend);
	const hasDefaultFixedMargin =
		Boolean(fixedSize) &&
		!config.margin &&
		!isHorizontalLegend &&
		!hasHtmlLegend &&
		!hasBottomRowLegend;
	const baseMargin =
		(config.margin
			? {
					...config.margin,
					...(isHorizontalLegend && {
						right: (config.margin.right ?? 0) + horizontalLegendMargin,
					}),
			  }
			: undefined) ??
		(isHorizontalLegend
			? {
					top: interactionMargin,
					right: horizontalLegendMargin,
					bottom: interactionMargin,
					left: 0,
			  }
			: hasHtmlLegend
			  ? { top: 0, right: 0, bottom: 0, left: 0 }
			  : hasBottomRowLegend
				  ? {
							...DEFAULT_DONUT_LEGEND_MARGIN,
							left: interactionMargin,
							right: interactionMargin,
					  }
				  : hasDefaultFixedMargin
					  ? {
								left: 0,
								right: 0,
								top: interactionMargin,
								bottom: 0,
						  }
					  : undefined);
	if (!categorical || !fixedSize || !baseMargin) {
		return config;
	}

	return {
		...config,
		margin: {
			...baseMargin,
			top:
				(baseMargin.top ?? 0) +
				(config.margin || hasHtmlLegend ? interactionMargin : 0),
			right: (baseMargin.right ?? 0) + interactionMargin,
			bottom:
				(baseMargin.bottom ?? 0) +
				(hasHtmlLegend
					? interactionMargin
					: hasLegend
					  ? Math.max(0, legendRows - 1) * legendRowHeight
					  : interactionMargin),
			left: (baseMargin.left ?? 0) + interactionMargin,
		},
	};
};

export const getDonutChartDimensions = (
	config: DonutConfig,
	width: string,
	settings: DonutChartSettings,
) => {
	const { fixedSize, interactionMargin, legendRows, legendRowHeight } =
		settings;
	const hasLegend = Boolean(config.legends?.length);
	const hasArcLinkLabels = config.enableArcLinkLabels !== false;
	const hasHtmlLegend = config.legendLayout === "html" && hasLegend;
	const configuredMargin = config.margin;
	const isHorizontalLegendLayout = isHorizontalDonutLegend(config);
	const htmlLegendItemHeight = HTML_LEGEND_ITEM_HEIGHT;
	const htmlLegendHeight =
		HTML_LEGEND_PADDING +
		htmlLegendItemHeight +
		Math.max(0, legendRows - 1) *
			(HTML_LEGEND_ITEM_HEIGHT + HTML_LEGEND_ROW_GAP);
	const fixedDonutAreaHeight =
		(configuredMargin?.top ?? 0) +
		(configuredMargin?.bottom ?? 0) +
		interactionMargin * 2;
	const legendVerticalMargin = isHorizontalLegendLayout
		? interactionMargin * 2
		: (configuredMargin?.top ?? DEFAULT_DONUT_MARGIN.top) +
		  (configuredMargin?.bottom ?? DEFAULT_DONUT_MARGIN.bottom) +
		  (hasHtmlLegend
				? interactionMargin * 2
				: hasLegend || configuredMargin
				  ? interactionMargin
				  : 0) +
		  (hasHtmlLegend
				? htmlLegendHeight
				: Math.max(0, legendRows - 1) * legendRowHeight);
	// Keep the board at the available width so fixed-size categorical donuts
	// without legends can center their chart within the container.
	const chartWidth = width;
	const chartHeight = fixedSize
		? `${
				DONUT_SIZE_PIXELS[fixedSize] +
				(isHorizontalLegendLayout || (!hasLegend && !hasArcLinkLabels)
					? fixedDonutAreaHeight
					: hasHtmlLegend
					  ? fixedDonutAreaHeight + htmlLegendHeight
					  : hasLegend
						  ? legendVerticalMargin
						  : hasArcLinkLabels
							  ? 28 + interactionMargin * 2
							  : 0)
		  }px`
		: undefined;

	return { chartWidth, chartHeight };
};

export const getCategoricalDonutSizeConfig = <
	T extends {
		fit?: boolean;
		innerRadius?: number;
		arcLinkLabelsOffset?: number;
		arcLinkLabelsStraightLength?: number;
	},
>(
	config: T,
	size: DonutSize,
) => ({
	...config,
	fit: false,
	innerRadius: config.innerRadius ?? (size === "small" ? 0.75 : 0.65),
	...(size === "small" && {
		arcLinkLabelsOffset: config.arcLinkLabelsOffset ?? 0,
		arcLinkLabelsStraightLength: config.arcLinkLabelsStraightLength ?? 24,
	}),
});
