import type { DefaultRawDatum } from "@harbor-charts/pie";
import { toggleDonutLegendPopover } from "../../components/chart-donut/chart-util";

type DonutConfig = {
	data?: ReadonlyArray<unknown>;
	colors?: unknown;
	id?: string | ((datum: DefaultRawDatum) => string | number);
	legends?: ReadonlyArray<unknown>;
	legendLayout?: "svg" | "html";
	pattern?: boolean;
	legendTooltip?: (...args: unknown[]) => unknown;
	tooltip?: unknown;
};

type LegendDatum = {
	id: string | number;
	label: string;
	color: string;
	index: number;
};
type ArcEvent = "mouseover" | "mouseout" | "focusin" | "focusout" | "click";
const SVG_NAMESPACE = "http://www.w3.org/2000/svg";
const CATEGORICAL_PATTERN_COUNT = 12;

const getCategoricalPatternId = (index: number) =>
	`viz-categorical-pattern-${(index % CATEGORICAL_PATTERN_COUNT) + 1}`;

const isNoValueLegendItem = (id: string | number) => {
	const normalizedId = String(id).toLowerCase();
	return normalizedId.includes("no data") || normalizedId === "null";
};

const getLegendData = (config: DonutConfig): LegendDatum[] => {
	const legend = config.legends?.[0] as Record<string, unknown> | undefined;
	const configuredData = Array.isArray(legend?.data) ? legend.data : null;
	const data = configuredData ?? config.data ?? [];
	const colors = Array.isArray(config.colors) ? config.colors : [];
	const idAccessor = config.id ?? "id";

	return data.map((datum, index) => {
		const record = datum as Record<string, unknown>;
		const id = configuredData
			? record.id ?? index
			: typeof idAccessor === "function"
			  ? idAccessor(record as unknown as DefaultRawDatum)
			  : record[idAccessor] ?? index;
		return {
			id: id as string | number,
			label: String(record.label ?? id),
			color: String(
				record.color ??
					colors[index] ??
					`var(--viz-color-categorical-${index + 1}-default)`,
			),
			index,
		};
	});
};

const getChartPattern = (board: HTMLElement, patternId: string) => {
	const chart = board.querySelector<HTMLElement>('[class~="--donut-chart"]');
	return Array.from(
		chart?.querySelectorAll<SVGPatternElement>("svg defs pattern") ?? [],
	).find((element) => element.id === patternId);
};

const createLegendSymbol = (
	board: HTMLElement,
	{ id, color, index }: LegendDatum,
	pattern: boolean,
) => {
	const isNoValue = isNoValueLegendItem(id);
	const usePattern = pattern || isNoValue;
	if (!usePattern) {
		const symbol = document.createElement("span");
		symbol.className = "chart-donut__categorical-legend-symbol";
		symbol.style.backgroundColor = color;
		symbol.setAttribute("aria-hidden", "true");
		return symbol;
	}

	const patternId = isNoValue
		? "no-value-pattern"
		: getCategoricalPatternId(index);
	const symbol = document.createElementNS(SVG_NAMESPACE, "svg");
	symbol.classList.add("chart-donut__categorical-legend-symbol");
	symbol.setAttribute("viewBox", "0 0 16 16");
	symbol.setAttribute("width", "16");
	symbol.setAttribute("height", "16");
	symbol.setAttribute("aria-hidden", "true");
	const sourcePattern = getChartPattern(board, patternId);
	if (sourcePattern) {
		const defs = document.createElementNS(SVG_NAMESPACE, "defs");
		defs.append(sourcePattern.cloneNode(true));
		symbol.append(defs);
	}
	const rect = document.createElementNS(SVG_NAMESPACE, "rect");
	rect.setAttribute("width", "16");
	rect.setAttribute("height", "16");
	rect.setAttribute("rx", "2");
	rect.setAttribute(
		"fill",
		isNoValue || sourcePattern ? `url(#${patternId})` : color,
	);
	if (isNoValue) {
		rect.setAttribute("stroke-width", "0");
		rect.setAttribute("stroke", "transparent");
		rect.style.pointerEvents = "none";
	}
	symbol.append(rect);
	return symbol;
};

const dispatchArcEvent = (board: HTMLElement, id: string, type: ArcEvent) => {
	const path = Array.from(
		board.querySelectorAll<SVGPathElement>("[datum-id]"),
	).find((element) => element.getAttribute("datum-id") === id);
	if (!path) return;
	path.dispatchEvent(
		type === "focusin" || type === "focusout"
			? new FocusEvent(type, { bubbles: true })
			: new MouseEvent(type, { bubbles: true }),
	);
};

const handleLegendEvent = (
	board: HTMLElement,
	config: DonutConfig,
	event: Event,
) => {
	const button = (event.target as Element).closest<HTMLButtonElement>(
		".chart-donut__categorical-legend-item",
	);
	if (!button) return;
	const relatedTarget = (event as MouseEvent | FocusEvent)
		.relatedTarget as Node | null;
	if (
		(event.type === "mouseover" || event.type === "mouseout") &&
		relatedTarget &&
		button.contains(relatedTarget)
	) {
		return;
	}
	const id = button.dataset.id;
	if (id === undefined) return;
	dispatchArcEvent(
		board,
		id,
		{
			mouseover: "mouseover",
			mouseout: "mouseout",
			focus: "focusin",
			blur: "focusout",
			click: "click",
		}[event.type] as ArcEvent,
	);
	const tooltip = board.querySelector("hbr-popover") as HTMLHbrPopoverElement;
	if (event.type === "mouseover" || event.type === "focus") {
		toggleDonutLegendPopover(tooltip, event, id, button.dataset.color, config);
	} else if (event.type === "click") {
		event.stopPropagation();
		toggleDonutLegendPopover(tooltip, event, id, button.dataset.color, config);
	} else {
		toggleDonutLegendPopover(tooltip);
	}
};

export const renderDonutHtmlLegend = (
	board: HTMLElement,
	config: DonutConfig,
) => {
	const legend = config.legends?.[0] as Record<string, unknown> | undefined;
	const isHorizontalLegend = legend?.horizontal === true;
	const isBottomRow =
		!legend ||
		((legend.anchor ?? (isHorizontalLegend ? "right" : "bottom")) ===
			"bottom" &&
			(legend.direction ?? (isHorizontalLegend ? "column" : "row")) === "row");
	const data = isBottomRow ? getLegendData(config) : [];
	let container = board.querySelector<HTMLDivElement>(
		".chart-donut__categorical-legend",
	);
	if (!data.length || (config.legendLayout !== "html" && !isBottomRow)) {
		container?.remove();
		return;
	}
	if (!container) {
		container = document.createElement("div");
		container.slot = "legend";
		container.className = "chart-donut__categorical-legend";
		container.setAttribute("role", "list");
		board.append(container);
	}
	container.replaceChildren(
		...data.map((legendDatum) => {
			const button = document.createElement("button");
			button.type = "button";
			button.className = "chart-donut__categorical-legend-item";
			button.setAttribute("role", "listitem");
			button.dataset.id = String(legendDatum.id);
			button.dataset.color = legendDatum.color;
			button.onfocus = (event) => handleLegendEvent(board, config, event);
			button.onblur = (event) => handleLegendEvent(board, config, event);
			button.append(
				createLegendSymbol(board, legendDatum, config.pattern === true),
				document.createTextNode(legendDatum.label),
			);
			return button;
		}),
	);
	container.onmouseover = (event) => handleLegendEvent(board, config, event);
	container.onmouseout = (event) => handleLegendEvent(board, config, event);
	container.onclick = (event) => handleLegendEvent(board, config, event);
};
